    val MAP: Map<String, DuaText> = mapOf(
        "dua_sharri_ma_amiltu" to DuaText("ከተግባሬ ክፋት መሸሸግ", "አላህ ሆይ ከሰራሁት ክፋትና ካልሰራሁት ክፋት በአንተ እጠበቃለሁ።", "የነብዩ ዱአ ﷺ እንደ አይሻ (RA)።", "የተደረገውም ሆነ ያልተቀለበሰው ነገር ከሚያስከትለው መዘዝ ጥበቃ።"),
        "dua_jahdil_bala" to DuaText("ከከባድ ፈተናዎች መሸሽ", "አላህ ሆይ ከከባድ ፈተና፣ ከመከራ፣ ከመጥፎ ትእዛዝ እና ከጠላቶች ጉጉት በአንተ እጠበቃለሁ።", "ከከባድ ፈተናዎች እና ከጠላቶች መኩራራት መሸሽ።", "ነቢዩ ﷺ ከእነዚህ አራት ነገሮች መጠጊያ ፈልገዋል።"),
        "dua_fitnat_ghina_faqr" to DuaText("ከሀብትና ድህነት ፈተናዎች መሸሸጊያ", "አላህ ሆይ ከስንፍናና ከእርጅና፣ ከኃጢአትና ከዕዳ፣ ከመቃብር ፈተናና ቅጣት፣ ከእሳት ፈተናና ቅጣት፣ ከሀብት ፈተና ክፋት፣ ከድህነት ፈተና በአንተ እጠበቃለሁ።", "ከመቃብር፣ ከጀሀነም፣ ከሀብትና ከድህነት (የዱዓው ክፍል) ፈተናዎች መሸሸጊያ።", "ከነብዩ ﷺ አጠቃላይ የጥገኝነት ዱአ።"),
        "dua_kufr_faqr" to DuaText("ከክህደት እና ከድህነት መሸሸጊያ", "አላህ ሆይ ከኩፍርና ከድህነት በአንተ እጠበቃለሁ ከቀብር ቅጣትም በአንተ እጠበቃለሁ። ከአንተ በቀር አምላክ የለም።", "ሶስት ጊዜ ጥዋት እና ማታ.", "አቡበክራህ (RA) ነብዩ ﷺ ሲናገሩ ሰሙ።"),
        "dua_sharri_sami" to DuaText("ከስሜት ህዋሴ ክፋት መሸሽ", "አላህ ሆይ ከመስማት ክፋት፣ ከዓይኔ ክፉ፣ ከአንደበቴ ክፉ፣ ከልቤ ክፋትና ከምኞቴ ክፋት በአንተ እጠበቃለሁ።", "ለሸካል ኢብኑ ሁመይድ (RA) ተማረ።", "እጅና እግር እና እራስን ከኃጢአት ለመጠበቅ ዱዓ።"),
        "dua_hadm_gharaq" to DuaText("ከድንገተኛ ሞት እና አደጋዎች መሸሸጊያ", "አላህ ሆይ ከመፈራረስ (በግንባታ)፣ ከከፍታ ላይ ከመውደቅ፣ ከመስመጥ፣ ከመቃጠል እና ከእርጅና በአንተ እጠበቃለሁ። በሞት ጊዜ ከሰይጣን፣ ከመንገድህ ሸሽቼ እንዳልሞት፣ በንዴት ከመሞትም አሳመኝ።", "ከአደጋ እና ከመጥፎ ሞት መሸሸጊያ.", "ከነብዩ የመሸሸጊያ ዱዓ ﷺ።"),
        "dua_ju_khiyanah" to DuaText("ከረሃብ እና ክህደት መሸሽ", "አላህ ሆይ ከረሃብ እጠበቃለሁ እሱ መጥፎ ጓደኛ ነውና ከክህደትም በአንተ እጠበቃለሁ እሱ መጥፎ መታመን ነውና።", "ከረሃብ እና ክህደት መሸሸጊያ.", "ከነብዩ የመሸሸጊያ ዱዓ ﷺ።"),
        "dua_huda_tuqa" to DuaText("መመሪያ፣ እግዚአብሔርን መምሰል፣ ንጽህና እና በቂነት", "አሏህ ሆይ መመሪያን፣ ፈሪሀን፣ ንፅህናን እና እራስን መቻልን እለምንሃለሁ።", "አጭር፣ አጠቃላይ የነብዩ ዱአ ﷺ።", "አራት የሃይማኖት እና የዚህ ዓለም በረከቶች።"),
        "dua_aslih_li_dini" to DuaText("ኃይማኖቴን አስተካክል አለም እና ወዲያ", "አላህ ሆይ የጉዳዮቼ ሁሉ ጠባቂ የሆነውን ሃይማኖቴን አስተካክል። በውስጧ መኖሬ ያለባትን ቅርቢቱን ሕይወቴን አስተካክል። መጨረሻዬንም አስተካክል ወደ እርሷ እመለሳለሁ። ለበጎ ነገር ሁሉ ሕይወትን አብዝተኝ፣ ሞትንም ከክፉ ነገር ሁሉ እፎይታ አድርግልኝ።", "ሃይማኖትን, ዓለምን እና ወዲያን - ሦስቱም.", "አጠቃላይ የነብዩ ዱአ ﷺ።"),
        "dua_musarrifal_qulub" to DuaText("ልባችንን ወደ ታዛዥነትህ አዙር", "አላህ ሆይ ልቦችን ወደ አንተ ታዛዥነት ልባችንን መልስልን።", "ልብን በታዛዥነት ለመጠበቅ ዱዓ።", "የሰዎች ሁሉ ልቦች በአልረሕማን በሁለት ጣቶች መካከል ናቸው።"),
        "dua_jannah_nar" to DuaText("ጀነትን በመጠየቅ ከእሳት መሸሸጊያ", "አላህ ሆይ ጀነትን እለምንሃለሁ ከእሳትም እጠበቃለሁ።", "ከታሻህሁድ በኋላ ወይም በማንኛውም ጊዜ።", "ነቢዩ ﷺ እንዲህ አሉ፡- ዱዓችንም በዚህ ዙሪያ ያጠነጠነ ነበር።"),
        "dua_khayri_kullih" to DuaText("ሁሉም ጥሩ ፣ አሁን እና በኋላ", "አላህ ሆይ መልካሙን ነገር ሁሉ - ፈጣንና የዘገየውን፣ የማውቀውንና የማላውቀውን እለምንሃለሁ፣ እናም ከክፉ ነገር ሁሉ - ፈጣንና የዘገየ፣ የማውቀውንና የማላውቀውን በአንተ እጠበቃለሁ። አላህ ሆይ ጀነትን እለምንሃለሁ ወደ እርስዋም ቃልና ተግባር ባቀረብኩኝ ነገር ሁሉ ከእሳትም ከንግግርም ከስራዋም ባንተ እጠበቃለሁ።", "ነብዩ ﷺ ይህንን አጠቃላይ ዱዓ ለአይሻ (RA) (የዱዓው አካል) አስተምረውታል።", "መልካም ነገር ሁሉ የሚሰበስብ ዱዓ።"),
        "dua_ihdini_saddidni" to DuaText("ምራኝ እና ቀጥ አድርገኝ።", "አላህ ሆይ ምራኝ በቀና መንገድም ጠብቀኝ።", "ነቢዩ ﷺ አሊ (RA) አስተምረውታል።", "መመሪያን በመንገድ ላይ እንደመመራት፣ ሳዳድን ደግሞ እንደ ቀስት ቅንነት አስብ።"),
        "dua_hubbaka" to DuaText("የአላህን ፍቅር መለመን", "አላህ ሆይ ስለ ፍቅርህ፣ ለሚወዱህ ፍቅር እና ወደ ፍቅርህ የሚያደርገኝን ስራ እጠይቅሃለሁ። አሏህ ሆይ ፍቅርህን ከራሴ፣ ከቤተሰቦቼና ከቀዝቃዛ ውሀ በላይ ውደድልኝ።", "የዳውድ ዱአ (AS) በነቢዩ ﷺ የተያያዘ።", "የአላህ ፍቅር ትልቁ ሀብት ነው።"),
        "dua_filal_khayrat" to DuaText("መልካም ማድረግ እና ክፉን መተው", "አላህ ሆይ መልካም ስራ እንድሰራ፣ክፉ ስራን እንድተው እና ድሆችን እንድወድ እንድረዳኝ እለምንሀለሁ፣አንተም ይቅር እንድትለኝና እንድታዝንልኝ። ለሰዎችም መፈተኛን ባስቀደምክ ጊዜ ሳትፈተኑ ያዙኝ። ስለ ፍቅርህ፣ ለሚወዱህ ሰዎች ፍቅር እና ወደ ፍቅርህ የሚያቀርቡኝን የስራ ፍቅር እጠይቅሃለሁ።", "አላህ ይህንን ዱዓ ለነብዩ ﷺ በህልም አስተማረው።", "ነቢዩ ﷺ፡ እውነት ነው፡ ተማርና አስተምረው፡ አሉ።"),
        "dua_bi_ilmikal_ghayb" to DuaText("ሕይወት ጥሩ ሆኖ ልኑር", "አሏህ ሆይ ፣ በማይታየው ነገር እውቀትህ እና በፍጥረትህ ላይ ባለህ ሃይል - ህይወት ለእኔ እንደምትሻለኝ እስካወቅህ ድረስ ጠብቀኝ ፣ ሞትም እንደሚሻለኝ ስታውቅ ውሰደኝ። አላህ ሆይ በድብቅም ሆነ በአደባባይ አንተን ከመፍራት፣ በእርካታና በቁጣ የእውነትን ቃል፣ በድህነትና በሀብት ውስጥ ልከኝነትን እለምንሃለሁ።", "የአማር ኢብኑ ያሲር ጸሎት (RA) (የመክፈቻ ክፍል)።", "ነቢዩ ﷺ ይህንን ዱዓ በፀሎት አድርገዋል።"),
        "dua_ism_azam_mannan" to DuaText("ኢስም-አዛም፡ አል-ማንን", "አላህ ሆይ እለምንሃለሁ ምስጋና ሁሉ የአንተ ነውና። ከአንተ በቀር ሌላ አምላክ የለም። ጸጋን ሰጪ ሰማያትንና ምድርን የፈጠረ። የግርማና የክብር ባለቤት ሆይ፣ ህያው ሆይ፣ ጠባቂ ሆይ!", "ነብዩ ﷺ ይህ ሰው በአላህ ታላቅ ስም ዱአ አድርጓል ብለዋል።", "በዚህ ስም የተሰራ ዱዓ ተመለሰ።"),
        "dua_ism_azam_ahad_samad" to DuaText("ኢስም-አዛም፡- አል-አሃድ አስ-ሳማድ", "አላህ ሆይ እለምንሃለሁ አንተ አላህ መሆንህን እመሰክራለሁና; ከአንተ በቀር ሌላ አምላክ የለም ከአንተ በስተቀር ሌላ አምላክ የለም።", "ነብዩ ﷺ ይህ ሰው አላህን በታላቅ ስሙ ጠየቀ።", "ሲጠየቅ ይሰጣል; ሲጠራው መልሶ ይመልሳል።"),
        "dua_thabbitni_hadiyan" to DuaText("የጸና፣ የሚመራ እና የሚመራ አድርገኝ።", "አላህ ሆይ አፅናኝ፣የሚመራኝና የምመራም አድርገኝ።", "ነብዩ ﷺ ይህንን ዱዓ ለጃሪር (RA) አደረጉ (ለራሶት 'ጠቢቲኒ' ይበሉ)።", "የጃሪር (RA) ኦሪጅናል ዱዓ 'thabbit-hu' የሚሉትን ቃላት ይጠቀማል።"),
        "dua_rabbighfir_tub_alayya" to DuaText("ይቅር በለኝ ንስሐንም ተቀበል", "ጌታዬ ሆይ ይቅር በለኝ ንስሀንም ተቀበል። አንተ ጸጸትን ተቀባይ አዛኙ ነህና።", "በአንድ መቀመጫ ውስጥ አንድ መቶ ጊዜ - የነቢዩ ልምምድ ﷺ.", "ሰሃቦች ነብዩን ﷺ መቶ ጊዜ በአንድ ቁጭ ብለው ቆጠሩት።"),
        "dua_rafiq_ala" to DuaText("የሟች ሰው ዱዓ", "አሏህ ሆይ ይቅር በለኝ እዘንልኝ ከከፍተኛው ሰሃባ ጋር ተባበረኝ።", "የነቢዩ የመጨረሻ ዱዓ ﷺ - ለታመመው ሰው ለራሱ እንዲናገር.", "ነብዩ ﷺ ይህንን ዱዓ ያደረጉት በሞቱበት ወቅት ነው።"),
        "dua_la_bas_tahur" to DuaText("የታመሙትን ማጽናናት: መንጻት", "ምንም ጉዳት የለውም; አላህ ቢሻ (ከኀጢአት) ማጥራት ነው።", "ሲጎበኙ የታመሙትን ለማጽናናት.", "ነቢዩ ﷺ የታመሙትን ሲጎበኙ ይህን ተናግሯል."),
        "dua_talqeen" to DuaText("ታልኪን ለሟች", "ሊመለክ የሚገባው አላህ ብቻ ነው።", "በሟች ሰው አጠገብ ካሊማውን አንብቡ (እንዲናገሩ አያስገድዷቸው)።", "የመጨረሻ ቃሉ ላ ኢላሀ ኢለላህ የሆነ ሰው ጀነት ይገባል (አቡ ዳዉድ 3116)።"),
        "dua_ahyini_ma_kanat" to DuaText("ሞትን ከመመኘት ይልቅ", "አላህ ሆይ ህይወቴ እስከምትሻልኝ ድረስ ጠብቀኝ ሞት ሲሻለኝም ውሰደኝ።", "በችግር ውስጥ ሞትን ከመመኘት ይልቅ.", "ነቢዩ ﷺ ሞትን መመኘትን ከልክለው በምትኩ ይህንን አስተማሩ።"),
        "dua_for_one_i_cursed" to DuaText("በቃላት የምጎዳ ሰው", "አላህ ሆይ የሰደብኩት ሙእሚን ሁሉ በትንሳኤ ቀን ወደ አንተ መቃረቢያ መንገድ አድርጊለት።", "በቁጣ ክፉ ለምትናገረው ሰው።", "የነቢዩ ዱአ ﷺ።"),
        "dua_praising_someone" to DuaText("ሰውን ሲያመሰግን", "እኔ ይህን እና የመሳሰሉትን ነው የምቆጥረው አላህም ተቆጣጣሪው ነውና የማንንም ንፅህና በአላህ ፊት አልሰጥም።", "አንድን ሰው ሲያመሰግኑ, ከማጋነን ይልቅ.", "ነቢዩ ﷺ ይህንን የምስጋና ሥነ ሥርዓት አስተማሩ።"),
        "dua_being_praised" to DuaText("ስትመሰገን", "አላህ ሆይ በተናገሩት ነገር አትጠይቀኝ የማያውቁትንም ይቅር በለኝ።", "(RA) እራስን ማሞገስ ሲሰማ - የአንድ ባልደረባ ልምምድ.", "ሲወደስ ትዕቢትን የማስወገድ ዘዴ።"),
        "dua_non_muslim_sneezes" to DuaText("ሙስሊም ያልሆነ ሰው ሲያስነጥስ", "አላህ ይምራህ ጉዳይህን ያስተካክል።", "ሙስሊም ያልሆነ ሰው ሲያስነጥስ አልሀምዱሊላህ እያለ።", "አይሁዶች ነቢዩ ﷺ 'ያርሀሙካላህ' እንደሚሉ ተስፋ አድርገው ያስነጥሱ ነበር እና ይህን ይላቸዋል።"),
        "dua_reply_ahl_kitab_salam" to DuaText("የመጽሐፉ ሰዎች ሰላም ምላሽ", "እና በአንተ ላይ።", "የመፅሀፉ ሰዎች በሰላም ሲሳለሙ።", "የነቢዩ መመሪያ ﷺ."),
        "dua_fasting_invited" to DuaText("በጾም ጊዜ ሲጋበዙ", "እየጾምኩ ነው።", "በጾም ጊዜ ሲጋበዙ ወይም አንድ ሰው ከእርስዎ ጋር ሲጣላ.", "ጾመኛው ግብዣ ከተቀበለ ለአስተናጋጁ መጸለይ አለበት።"),
        "dua_for_who_gave_drink" to DuaText("ለሚበላኝ", "አላህ ሆይ የበላኝን አብላው ያጠጣኝንም አጠጣኝ።", "ምግብና መጠጥ ለሚሰጣችሁ።", "ነብዩ ﷺ ይህንን ዱዓ ያደረጉት ለአል-ሚቅዳድ (RA) ነው።"),
        "dua_eid_greeting" to DuaText("የኢድ ሰላምታ", "አላህ ከኛ እና ካንተ (በጎ ስራ) ይቀበል።", "እርስ በእርሳቸው በዒድ ቀን - የተከበሩ ሰሃቦች ልምምድ (RA).", "ሶሓቦች በዒድ ቀን ሲገናኙ እንዲህ አሉ።"),
        "dua_wedding_night" to DuaText("ከኒካህ በኋላ ለሙሽሪት", "አሏህ ሆይ ለሷ መልካም እና የፈጠርካትን የተፈጥሮ መልካም ነገር እለምንሃለሁ ከክፋትዋ እና ከፈጠርካት የተፈጥሮ መጥፎነት በአንተ እጠበቃለሁ።", "ከኒካህ በኋላ እጅን በሚስቱ ግንባር ላይ በማድረግ።", "የነቢዩ ﷺ ትምህርት - በረከት በትዳር ውስጥ።"),
        "dua_istisqa_ibadak" to DuaText("አገልጋዮችህን እና እንስሳትህን አጠጣ", "አሏህ ሆይ ለባሮችህና ለእንስሳትህ አጠጣ እዝነትህን ዘርግተህ ለሞተች ምድርህ ህይወትን ስጥ።", "ዝናብ መጠየቅ (ኢስቲስካ)።", "ነቢዩ ﷺ ይህን ዱዓ ለዝናብ አደረጉ።"),
        "dua_seeing_clouds" to DuaText("ጨለማ ደመናን ማየት", "አላህ ሆይ ከክፋቱ በአንተ እጠበቃለሁ።", "በሰማይ ውስጥ ጥቁር ደመናዎችን ሲያዩ; ዝናብ ከዘነበ \"አላሙማ ሰዪባን ናፊዓ\" በል።", "ደመና ሲያዩ ነቢዩ ﷺ የሚያደርጉትን ትተው ይህንን ዱዓ ያደርጋሉ።"),
        "dua_jamarat" to DuaText("ጀማራትን በድንጋይ መውገር", "አላህ ታላቅ ነው።", "በእያንዳንዱ ጠጠር.", "ነብዩ ﷺ ከእያንዳንዱ ጠጠር ጋር ተክቢር ተናግረዋል ከዛም የመጀመሪያ እና ሁለተኛ ጀምራ በኋላ ቂብላን ገጠሙ እና ረጅም ዱዓ አደረጉ።"),
        "dua_rabbi_ainni" to DuaText("ጌታዬ ሆይ እርዳኝ እንጂ በእኔ ላይ አትሁን", "ጌታዬ ሆይ እርዳኝ ሌሎችንም በኔ ላይ አትርዳኝ፣ ድልን ስጠኝ፣ ሌሎችንም በኔ ላይ አትሸነፍ፣ አቅደኝ፣ በእኔም ላይ አታስብብኝ፣ ምራኝ፣ መመሪያዬንም አገራልኝ፣ በሚበድለኝም ሰው ላይ እርዳኝ።", "አጠቃላይ የነብዩ ዱአ ﷺ (የመክፈቻ ክፍል)።", "በሃይማኖት እና በዚህ ዓለም ውስጥ ሁሉንም እርዳታ የሚሰበስብ ዱዓ።"),
        "dua_ati_nafsi_taqwaha" to DuaText("ነፍሴን ታቅዋ ስጣት", "አሏህ ሆይ ነፍሴን ፈሪሀነቷን ስጣት እና አጥራዋት አንተ ከማጥራት በላጭ ነህና። አንተ ጠባቂዋ እና ጌታዋ ነህ።", "ራስን ለማደስ እና ለማፅዳት።", "ነብዩ ﷺ ይህንን ዱዓ ያደርጉ ነበር።"),
        "dua_iqsim_lana_khashyatik" to DuaText("እንደዚህ አይነት ፍርሃትህን ስጠን", "O Allah, grant us enough fear of You to come between us and disobeying You, enough obedience to bring us to Your Paradise, and enough certainty to make the calamities of this world easy for us. በህይወት እስካቆየን ድረስ በመስማት፣ በአይናችን እና በጥንካሬያችን እንዝናና እና ከኛ በላይ ያደረጋቸው። Take our revenge on those who wrong us, help us against our enemies, do not let our calamity be in our religion, do not make this world our greatest concern or the limit of our knowledge, and do not set over us those who will show us no mercy.", "ከስብሰባ ሲነሱ - ነቢዩ ﷺ ይህን ዱዓ ሳያደርጉ ተነሱ.", "ሁሉን አቀፍ ዱዓ ለሀይማኖት ፣ለዱንያ እና ለመጨረሻው አለም።"),
        "dua_infani_bima_allamtani" to DuaText("ያስተማርከኝን ተጠቀሙኝ።", "አላህ ሆይ ባስተማርከኝ ተጠቀምኝ የሚጠቅመኝን አስተምረኝ እውቀትንም ጨምርልኝ።", "እውቀትን በሚፈልጉበት ጊዜ ወይም ከማጥናት በፊት.", "የሚጠቅም እውቀት ለማግኘት እና በእሱ ላይ ለመስራት ዱዓ።"),
    )
}
